import pandas as pd
import numpy as np

# Load data
df = pd.read_csv('chunks_csv/moran_local_no2crime_no2_Q1_2021.csv')
adj_df = pd.read_csv(ADJACENCY_PATH)

# Drop boroughs with missing values
df = df.dropna(subset=['value']).reset_index(drop=True)

# Build adjacency dict (symmetric)
boroughs = df['borough'].tolist()
adjacency = {b: set() for b in boroughs}
for _, row in adj_df.iterrows():
    b, nbr = row['borough'], row['neighbor']
    if b in adjacency and nbr in adjacency:
        adjacency[b].add(nbr)
        adjacency[nbr].add(b)

# Map boroughs to indices and values
idx = {b: i for i, b in enumerate(boroughs)}
n = len(boroughs)
x = df['value'].values
xbar = x.mean()
s2 = np.sum((x - xbar)**2) / n

# Precompute neighbor indices
neighbors = {i: [idx[nbr] for nbr in adjacency[b]] for b,i in idx.items()}

# Compute observed local Moran's I
obs_I = np.zeros(n)
for b, i in idx.items():
    nbr_idx = neighbors[i]
    if nbr_idx:
        obs_I[i] = (x[i] - xbar) * np.sum(x[nbr_idx] - xbar) / s2
    else:
        obs_I[i] = np.nan

# Permutation test
np.random.seed(0)
n_perm = 500
perm_I = np.zeros((n, n_perm))
for perm in range(n_perm):
    x_perm = np.random.permutation(x)
    for i in range(n):
        nbr_idx = neighbors[i]
        if nbr_idx:
            perm_I[i, perm] = (x_perm[i] - xbar) * np.sum(x_perm[nbr_idx] - xbar) / s2
        else:
            perm_I[i, perm] = np.nan

# Compute p-values
p_vals = np.ones(n)
for i in range(n):
    if not np.isnan(obs_I[i]):
        if obs_I[i] > 0:
            p_vals[i] = (np.sum(perm_I[i] >= obs_I[i]) + 1) / (n_perm + 1)
        else:
            p_vals[i] = (np.sum(perm_I[i] <= obs_I[i]) + 1) / (n_perm + 1)

# Identify hotspots and cold spots
hotspots = []
coldspots = []
for b, i in idx.items():
    if np.isnan(obs_I[i]):
        continue
    if p_vals[i] < 0.05:
        if x[i] > xbar and obs_I[i] > 0:
            hotspots.append((b, obs_I[i], p_vals[i]))
        if x[i] < xbar and obs_I[i] < 0:
            coldspots.append((b, obs_I[i], p_vals[i]))

# Prepare final answer
results = []
for b, Ii, pi in hotspots:
    results.append(f"{b} (HH, I={Ii:.4f})")
for b, Ii, pi in coldspots:
    results.append(f"{b} (LL, I={Ii:.4f})")

final = "none" if not results else ", ".join(results)
print(f"FINAL ANSWER: {final}")
